#include <stdio.h>
#include <driver/gpio.h>
#include <freertos/FreeRTOS.h>
#include <esp_timer.h>
#include <esp_rom_sys.h>
#include <freertos/task.h>

#define TRIG GPIO_NUM_14
#define ECHO GPIO_NUM_27
#define ECHO_TIMEOUT_US 30000   // ~5 m max range

void app_main(void)
{
    gpio_set_direction(TRIG, GPIO_MODE_OUTPUT);
    gpio_set_direction(ECHO, GPIO_MODE_INPUT);
    gpio_set_level(TRIG, 0);
    while(1){
        // 10 us trigger pulse
        gpio_set_level(TRIG, 1);
        esp_rom_delay_us(10);
        gpio_set_level(TRIG, 0);

        int64_t timeout = esp_timer_get_time() + ECHO_TIMEOUT_US;
        // wait for echo to go high
        while(!gpio_get_level(ECHO) && esp_timer_get_time() < timeout);
        int64_t start = esp_timer_get_time();
        // measure how long echo stays high
        while(gpio_get_level(ECHO) && esp_timer_get_time() < timeout);
        int64_t end = esp_timer_get_time();

        if(end >= timeout){
            printf("no echo\n");
        } else {
            double velocity = 0.0343;   // speed of sound in cm/us
            double distance = (end - start) * velocity / 2;
            printf("distance: %.1f cm\n", distance);
        }
        vTaskDelay(pdMS_TO_TICKS(1000));
    }
}

